#include <Arduino.h>
#include <SPI.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>
#include <RTClib.h>
#include <stdio.h>

RTC_DS1307 rtc;
Adafruit_ILI9341 lcd(10, 9, 8);
const char* weekdays[] = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
struct Button {
  uint8_t pin;
  bool raw;
  bool stable;
  unsigned long changed;
};
Button previousButton = {3, false, false, 0};
Button nextButton = {2, false, false, 0};
int32_t offsetDays = 0;
bool ready = false;
bool haveDrawn = false;
uint16_t drawnYear = 0;
uint8_t drawnMonth = 0;
uint8_t drawnDay = 0;

bool pressed(Button &b) {
  bool level = digitalRead(b.pin) == HIGH;
  unsigned long now = millis();
  if (level != b.raw) {
    b.raw = level;
    b.changed = now;
  }
  if (level != b.stable && now - b.changed >= 30) {
    b.stable = level;
    return level;
  }
  return false;
}

void showDate(const DateTime &selected) {
  char dateText[16];
  snprintf(dateText, sizeof(dateText), "%04u-%02u-%02u", (unsigned)selected.year(), (unsigned)selected.month(), (unsigned)selected.day());
  lcd.fillRect(0, 25, 240, 85, ILI9341_BLACK);
  lcd.setCursor(10, 30);
  lcd.print(dateText);
  lcd.setCursor(10, 80);
  lcd.print(weekdays[selected.dayOfTheWeek()]);
  drawnYear = selected.year();
  drawnMonth = selected.month();
  drawnDay = selected.day();
  haveDrawn = true;
}

void setup() {
  pinMode(3, INPUT);
  pinMode(2, INPUT);
  lcd.begin();
  lcd.fillScreen(ILI9341_BLACK);
  lcd.setTextSize(3);
  lcd.setTextColor(ILI9341_WHITE);
  ready = rtc.begin();
}

void loop() {
  if (!ready) return;
  if (pressed(previousButton)) --offsetDays;
  if (pressed(nextButton)) ++offsetDays;
  DateTime current = rtc.now();
  DateTime selected = current + TimeSpan(offsetDays * 86400L);
  if (!haveDrawn || selected.year() != drawnYear || selected.month() != drawnMonth || selected.day() != drawnDay) {
    showDate(selected);
  }
  delay(5);
}
